// Upgrade compatibility proof for users.removeModelAccount: persisted state is
// generated by the ACTUAL latest-stable storage code (spawned checkout, never
// hand-written JSON), then opened by this PR build through the normal Gateway
// startup path. Requires the synthetic fixture checkout:
//   B1_UPGRADE_SOURCE_CHECKOUT  directory of a checkout of the latest stable tag
//   B1_UPGRADE_SOURCE_COMMIT    required verified stable commit; mismatches fail
// Without B1_UPGRADE_SOURCE_CHECKOUT the test skips instead of fabricating state.
import { execFile } from "node:child_process";
import { X509Certificate } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";
import { promisify } from "node:util";
import { expect, it } from "vitest";
import type {
  UsersListModelAccountsResult,
  UsersRemoveModelAccountResult,
  UsersSelfResult,
} from "../../../packages/gateway-protocol/src/index.js";
import { TEST_TLS_CERT_PEM, TEST_TLS_KEY_PEM } from "../../../test/helpers/tls-fixture.js";
import { resolveDefaultSessionStorePath } from "../../config/sessions/paths.js";
import { loadSessionEntryReadOnly } from "../../config/sessions/session-accessor.js";
import type { GatewayAuthConfig } from "../../config/types.gateway.js";
import type { OpenClawConfig } from "../../config/types.openclaw.js";
import { resolveOpenClawStateSqlitePath } from "../../state/openclaw-state-db.paths.js";
import {
  createOpenClawTestState,
  type OpenClawTestState,
} from "../../test-utils/openclaw-test-state.js";
import { disconnectGatewayClient, startGatewayWithClient } from "../test-helpers.e2e.js";
import { KERNEL_TEST_ENV } from "../test-helpers.env.js";

const DOMAIN = "b1-upgrade.example.test";
const ORIGIN = "https://b1-upgrade-control.example.test";
const PINNED_SESSION = "agent:main:b1-pinned";
const KEPT_SESSION = "agent:main:b1-kept";
const SOURCE_CHECKOUT = process.env.B1_UPGRADE_SOURCE_CHECKOUT;
const SOURCE_COMMIT = process.env.B1_UPGRADE_SOURCE_COMMIT;

const trace = (line: string) => {
  console.log(`[b1-upgrade] ${line}`);
};

function readAccountRows(state: OpenClawTestState) {
  const database = new DatabaseSync(resolveOpenClawStateSqlitePath(state.env), { readOnly: true });
  try {
    return database
      .prepare(
        "SELECT name, scope_id, kind, deleted_at_ms FROM secret_store_entries" +
          " WHERE name LIKE 'model-account:%' ORDER BY scope_id, name",
      )
      .all() as Array<{
      name: string;
      scope_id: string;
      kind: string;
      deleted_at_ms: number | null;
    }>;
  } finally {
    database.close();
  }
}

function readSession(agentId: string, sessionKey: string) {
  return loadSessionEntryReadOnly({
    agentId,
    storePath: resolveDefaultSessionStorePath(agentId),
    sessionKey,
  });
}

/**
 * Spawns the latest-stable checkout's own code to build the persisted state.
 * The script imports the OLD repository modules by absolute URL, so module
 * resolution and schema ownership belong to the old build, not this one.
 */
async function generateStableState(state: OpenClawTestState, checkout: string, commit: string) {
  const script = await fs.mkdtemp(path.join(state.root, "old-generator-"));
  const scriptPath = path.join(script, "generate.mts");
  const moduleUrl = (relative: string) =>
    `file://${path.join(checkout, relative).split(path.sep).join("/")}`;
  await fs.writeFile(
    scriptPath,
    [
      `import { ensureProfileForEmail } from ${JSON.stringify(moduleUrl("src/state/user-profiles.js"))};`,
      `import { setUserProfileRole } from ${JSON.stringify(moduleUrl("src/state/user-profile-writes.worker.js"))};`,
      `import { connectUserModelAccountAsync } from ${JSON.stringify(moduleUrl("src/state/user-model-account-operations.js"))};`,
      `import { replaceSessionEntry } from ${JSON.stringify(moduleUrl("src/config/sessions/session-accessor.js"))};`,
      `import { resolveDefaultSessionStorePath } from ${JSON.stringify(moduleUrl("src/config/sessions/paths.js"))};`,
      `
const owner = ensureProfileForEmail("owner@${DOMAIN}").id;
const other = ensureProfileForEmail("other@${DOMAIN}").id;
setUserProfileRole(owner, "member");
async function connect(provider: string, label: string) {
  const connected = await connectUserModelAccountAsync({
    ownerProfileId: owner,
    credential: { type: "token", provider, token: "synthetic-b1-" + label, displayName: label },
    assertCurrent() {},
  });
  return connected.authProfileId;
}
const removed = await connect("b1-alpha", "removed");
const kept = await connect("b1-beta", "kept");
const foreign = (await connectUserModelAccountAsync({
  ownerProfileId: other,
  credential: { type: "token", provider: "b1-alpha", token: "synthetic-b1-foreign", displayName: "foreign" },
  assertCurrent() {},
})).authProfileId;
await replaceSessionEntry(
  { agentId: "main", storePath: resolveDefaultSessionStorePath("main"), sessionKey: ${JSON.stringify(PINNED_SESSION)} },
  {
    sessionId: "b1-pinned",
    updatedAt: 17,
    providerOverride: "b1-alpha",
    modelOverride: "b1-old-model",
    authProfileOverride: removed,
    authProfileOverrideSource: "user",
    modelFallback: {
      source: "agent-patch",
      ts: 1,
      prevModel: "b1-old-model",
      prevProvider: "b1-alpha",
      prevAuthProfileOverride: removed,
    },
  },
);
await replaceSessionEntry(
  { agentId: "main", storePath: resolveDefaultSessionStorePath("main"), sessionKey: ${JSON.stringify(KEPT_SESSION)} },
  { sessionId: "b1-kept", updatedAt: 18, authProfileOverride: kept },
);
process.stdout.write(JSON.stringify({ owner, other, removed, kept, foreign }));
`,
    ].join("\n"),
    "utf8",
  );
  const result = await promisify(execFile)(
    process.execPath,
    ["--import", path.join(checkout, "scripts", "tsx.mjs"), scriptPath],
    {
      cwd: checkout,
      encoding: "utf8",
      timeout: 120_000,
      env: {
        ...state.env,
        NODE_OPTIONS: undefined,
        B1_UPGRADE_SOURCE_COMMIT: undefined,
        B1_UPGRADE_SOURCE_CHECKOUT: undefined,
      },
    },
  );
  const seeded = JSON.parse(result.stdout) as {
    owner: string;
    other: string;
    removed: string;
    kept: string;
    foreign: string;
  };
  trace(
    `state generated by stable checkout ${commit.slice(0, 12)} (credential values never printed)`,
  );
  return seeded;
}

async function resolveUpgradeSource() {
  if (!SOURCE_CHECKOUT) {
    return undefined;
  }
  if (!SOURCE_COMMIT) {
    throw new Error("B1_UPGRADE_SOURCE_COMMIT must pin the independently verified stable release");
  }
  const commit = (
    await promisify(execFile)("git", ["-C", SOURCE_CHECKOUT, "rev-parse", "HEAD"], {
      encoding: "utf8",
    })
  ).stdout.trim();
  if (commit !== SOURCE_COMMIT) {
    throw new Error(
      `B1_UPGRADE_SOURCE_CHECKOUT is at ${commit}, expected ${SOURCE_COMMIT}; re-checkout the recorded stable tag`,
    );
  }
  const status = await promisify(execFile)(
    "git",
    ["-C", SOURCE_CHECKOUT, "status", "--porcelain"],
    {
      encoding: "utf8",
    },
  );
  if (status.stdout.trim()) {
    throw new Error("Stable upgrade source must have a clean working tree");
  }
  return { checkout: SOURCE_CHECKOUT, commit };
}

async function buildUpgradeConfig(state: OpenClawTestState) {
  const auth: GatewayAuthConfig = {
    mode: "trusted-proxy",
    trustedProxy: {
      userHeader: "x-forwarded-user",
      requiredHeaders: ["x-forwarded-proto"],
      allowUsers: [`owner@${DOMAIN}`],
      allowLoopback: true,
      deviceAutoApprove: { enabled: true, scopes: ["operator.read", "operator.write"] },
    },
  };
  const certPath = await state.writeText("tls/cert.pem", TEST_TLS_CERT_PEM);
  const keyPath = await state.writeText("tls/key.pem", TEST_TLS_KEY_PEM);
  const cfg = {
    agents: {
      entries: { main: {} },
      defaults: { workspace: state.workspaceDir, skipBootstrap: true },
    },
    plugins: { enabled: false, slots: { memory: "none" } },
    gateway: {
      auth,
      trustedProxies: ["127.0.0.1", "::1"],
      controlUi: { allowedOrigins: [ORIGIN] },
      tls: { enabled: true, autoGenerate: false, certPath, keyPath },
      roles: {
        default: "member",
        definitions: {
          member: {
            agents: "*",
            sessions: { others: "write" },
            scopes: ["operator.read", "operator.write"],
          },
        },
      },
    },
  } satisfies OpenClawConfig;
  return { cfg, auth };
}

async function startUpgradeGateway(
  state: OpenClawTestState,
  seeded: { owner: string },
  cfg: OpenClawConfig,
  auth: GatewayAuthConfig,
) {
  const gateway = await startGatewayWithClient({
    cfg,
    configPath: state.configPath,
    auth,
    secure: true,
    tlsFingerprint: new X509Certificate(TEST_TLS_CERT_PEM).fingerprint256,
    clientName: "openclaw-control-ui",
    mode: "webchat",
    origin: ORIGIN,
    scopes: ["operator.read", "operator.write"],
    edgeAuthHeaders: {
      "x-forwarded-user": `owner@${DOMAIN}`,
      "x-forwarded-proto": "https",
      "x-forwarded-for": "203.0.113.50",
    },
  });
  await gateway.server.startupSettled;
  const self = await gateway.client.request<UsersSelfResult>("users.self", {});
  expect(self.profile.id).toBe(seeded.owner);
  return gateway;
}

it.skipIf(!SOURCE_CHECKOUT)(
  "state written by the latest stable release loads, removes one account, and survives restart",
  { timeout: 420_000 },
  async () => {
    const source = await resolveUpgradeSource();
    if (!source) {
      throw new Error("upgrade source disappeared between collection and run");
    }
    const state = await createOpenClawTestState({
      label: "b1-upgrade",
      env: {
        ...KERNEL_TEST_ENV,
        VITEST: process.env.VITEST,
        OPENCLAW_TEST_MINIMAL_GATEWAY: undefined,
        OPENCLAW_DISABLE_BUNDLED_PLUGINS: "1",
        NO_PROXY: "127.0.0.1,localhost,::1",
        no_proxy: "127.0.0.1,localhost,::1",
      },
    });
    await using cleanup = new AsyncDisposableStack();
    cleanup.defer(() => state.cleanup());
    const seeded = await generateStableState(state, source.checkout, source.commit);
    const { cfg, auth } = await buildUpgradeConfig(state);
    // The supported upgrade path: this build's doctor owns state migrations. A
    // fresh gateway refuses older agent stores, so doctor --fix runs first,
    // against the same config the Gateway will use.
    await state.writeConfig(cfg);
    try {
      await promisify(execFile)(
        process.execPath,
        [
          path.resolve(process.cwd(), "scripts/run-node.mjs"),
          "doctor",
          "--fix",
          "--non-interactive",
          "--yes",
          "--no-workspace-suggestions",
        ],
        {
          cwd: process.cwd(),
          encoding: "utf8",
          timeout: 300_000,
          maxBuffer: 8 * 1024 * 1024,
          env: {
            ...state.env,
            PATH: process.env.PATH,
            B1_UPGRADE_SOURCE_COMMIT: undefined,
            B1_UPGRADE_SOURCE_CHECKOUT: undefined,
          },
        },
      );
    } catch (error) {
      const detail = error as { stdout?: string; stderr?: string };
      throw new Error(
        `doctor --fix failed on stable-generated state: ${String(error)}` +
          `; stdout tail: ${detail.stdout?.slice(-4_000) ?? ""}` +
          `; stderr tail: ${detail.stderr?.slice(-4_000) ?? ""}`,
        { cause: error },
      );
    }
    trace("doctor --fix completed on stable-generated state");
    const before = {
      rows: readAccountRows(state),
      pinned: readSession("main", PINNED_SESSION),
      kept: readSession("main", KEPT_SESSION),
    };
    expect(before.rows).toHaveLength(3);

    const gateway = await startUpgradeGateway(state, seeded, cfg, auth);
    cleanup.defer(async () => {
      await disconnectGatewayClient(gateway.client);
      await gateway.server.close({ reason: "b1 upgrade proof complete" });
    });
    const owner = gateway.client;
    // Snapshot after the Gateway has written its runtime config; removal must
    // not touch unrelated settings from here on.
    const configAtStart = await fs.readFile(state.configPath, "utf8");
    const listed = await owner.request<UsersListModelAccountsResult>("users.listModelAccounts", {});
    expect(listed.accounts.map((account) => account.authProfileId).toSorted()).toEqual(
      [seeded.kept, seeded.removed].toSorted(),
    );
    trace(
      `stable state loads on PR build: ${listed.accounts.length} owner accounts over transport`,
    );

    const removed = await owner.request<UsersRemoveModelAccountResult>("users.removeModelAccount", {
      authProfileId: seeded.removed,
    });
    expect(removed).toMatchObject({
      removed: true,
      sessionCleanup: "complete",
      links: [{ provider: "b1-beta", authProfileId: seeded.kept }],
    });
    const rows = readAccountRows(state);
    expect(rows.map((row) => row.name).toSorted()).toEqual(
      [`model-account:${seeded.kept}`, `model-account:${seeded.foreign}`].toSorted(),
    );
    const pinned = readSession("main", PINNED_SESSION);
    expect(pinned?.authProfileOverride).toBeUndefined();
    expect(pinned?.modelFallback?.prevAuthProfileOverride).toBeUndefined();
    expect(pinned).toMatchObject({ modelOverride: "b1-old-model" });
    expect(readSession("main", KEPT_SESSION)).toEqual(before.kept);
    expect(await fs.readFile(state.configPath, "utf8")).toEqual(configAtStart);
    trace(
      "one account removed: kept+foreign rows, unrelated settings, kept pin, and rollback metadata preserved",
    );

    // Reopen: stop the server, start a fresh Gateway on the same state, re-verify.
    await disconnectGatewayClient(owner);
    await gateway.server.close({ reason: "b1 upgrade restart" });
    const reopened = await startUpgradeGateway(state, seeded, cfg, auth);
    cleanup.defer(async () => {
      await disconnectGatewayClient(reopened.client);
      await reopened.server.close({ reason: "b1 upgrade restart complete" });
    });
    const relisted = await reopened.client.request<UsersListModelAccountsResult>(
      "users.listModelAccounts",
      {},
    );
    expect(relisted.accounts).toEqual([
      expect.objectContaining({ authProfileId: seeded.kept, provider: "b1-beta", selected: true }),
    ]);
    expect(readAccountRows(state)).toEqual(rows);
    expect(readSession("main", PINNED_SESSION)).toEqual(pinned);
    expect(readSession("main", KEPT_SESSION)).toEqual(before.kept);
    trace("restart on PR build: removal, selections, and unrelated state survive reopen");
  },
);
